import{_ as s,o as n,c as e,ag as o}from"./chunks/framework.1IVNT0ce.js";const y=JSON.parse('{"title":"Router","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/router.md","filePath":"concepts/router.md"}'),l={name:"concepts/router.md"};function t(p,a,r,i,c,d){return n(),e("div",null,[...a[0]||(a[0]=[o(`<h1 id="router" tabindex="-1">Router <a class="header-anchor" href="#router" aria-label="Permalink to &quot;Router&quot;">​</a></h1><p>The router is responsible for turning raw slash-command text into structured command data and validating arguments against schemas.</p><p>See also:</p><ul><li><a href="./commands">Commands</a></li><li><a href="./middleware">Middleware</a></li><li><a href="./../guides/adding-commands">Adding Commands</a></li></ul><h2 id="why-the-router-exists" tabindex="-1">Why The Router Exists <a class="header-anchor" href="#why-the-router-exists" aria-label="Permalink to &quot;Why The Router Exists&quot;">​</a></h2><p>Handlers should not need to re-parse command text manually. The router gives the rest of the framework one consistent parsed representation:</p><ul><li>command name</li><li>positional values</li><li>flags</li><li>raw text</li></ul><p>That representation is <code>ParsedCommand</code>.</p><h2 id="how-parsing-works-today" tabindex="-1">How Parsing Works Today <a class="header-anchor" href="#how-parsing-works-today" aria-label="Permalink to &quot;How Parsing Works Today&quot;">​</a></h2><p>The current parser:</p><ul><li>splits the line on whitespace</li><li>treats the first token as the command name</li><li>resolves aliases to the canonical command name</li><li>treats <code>--flag value</code> or <code>-f value</code> as flag/value pairs</li><li>treats standalone flags as boolean <code>True</code></li><li>collects everything else as positional args</li></ul><p>Example:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>/deploy prod --force</span></span></code></pre></div><p>Becomes:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#82AAFF;">ParsedCommand</span><span style="color:#89DDFF;">(</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    name</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/deploy</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    positional</span><span style="color:#89DDFF;">=[</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">prod</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">],</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    flags</span><span style="color:#89DDFF;">={</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">force</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> True},</span></span>
<span class="line"><span style="color:#BABED8;font-style:italic;">    raw</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/deploy prod --force</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">)</span></span></code></pre></div><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>If a command defines <code>args_schema</code>, the router maps the parsed values into that schema:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">from</span><span style="color:#BABED8;"> pydantic </span><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#BABED8;"> BaseModel</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C792EA;">class</span><span style="color:#FFCB6B;"> DeployArgs</span><span style="color:#89DDFF;">(</span><span style="color:#FFCB6B;">BaseModel</span><span style="color:#89DDFF;">):</span></span>
<span class="line"><span style="color:#BABED8;">    env</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> str</span></span>
<span class="line"><span style="color:#BABED8;">    force</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> bool</span><span style="color:#89DDFF;"> =</span><span style="color:#89DDFF;"> False</span></span></code></pre></div><p>For <code>/deploy prod --force</code>, validation produces:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#82AAFF;">DeployArgs</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">env</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">prod</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> force</span><span style="color:#89DDFF;">=True)</span></span></code></pre></div><h2 id="positional-mapping-rules" tabindex="-1">Positional Mapping Rules <a class="header-anchor" href="#positional-mapping-rules" aria-label="Permalink to &quot;Positional Mapping Rules&quot;">​</a></h2><p>Positional args are assigned to schema fields that are still missing after flags are applied, in schema declaration order.</p><p>That makes simple commands ergonomic, but it is also one of the places where the router stays intentionally simple.</p><h2 id="current-limitations" tabindex="-1">Current Limitations <a class="header-anchor" href="#current-limitations" aria-label="Permalink to &quot;Current Limitations&quot;">​</a></h2><h3 id="no-shell-quote-aware-parsing" tabindex="-1">No shell-quote aware parsing <a class="header-anchor" href="#no-shell-quote-aware-parsing" aria-label="Permalink to &quot;No shell-quote aware parsing&quot;">​</a></h3><p>This is the big one. The router splits on whitespace, so:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>/say hello world</span></span></code></pre></div><p>becomes two positionals, not one quoted string.</p><h3 id="no-nested-command-language" tabindex="-1">No nested command language <a class="header-anchor" href="#no-nested-command-language" aria-label="Permalink to &quot;No nested command language&quot;">​</a></h3><p>There is no built-in subcommand tree parser.</p><h3 id="flag-parsing-is-basic" tabindex="-1">Flag parsing is basic <a class="header-anchor" href="#flag-parsing-is-basic" aria-label="Permalink to &quot;Flag parsing is basic&quot;">​</a></h3><p>Flags are good enough for common <code>--name value</code> and <code>--flag</code> cases, but not for complex CLI grammar.</p><h2 id="realistic-example" tabindex="-1">Realistic Example <a class="header-anchor" href="#realistic-example" aria-label="Permalink to &quot;Realistic Example&quot;">​</a></h2><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">from</span><span style="color:#BABED8;"> pydantic </span><span style="color:#89DDFF;font-style:italic;">import</span><span style="color:#BABED8;"> BaseModel</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C792EA;">class</span><span style="color:#FFCB6B;"> RunArgs</span><span style="color:#89DDFF;">(</span><span style="color:#FFCB6B;">BaseModel</span><span style="color:#89DDFF;">):</span></span>
<span class="line"><span style="color:#BABED8;">    task</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> str</span></span>
<span class="line"><span style="color:#BABED8;">    retries</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> int</span><span style="color:#89DDFF;"> =</span><span style="color:#F78C6C;"> 0</span></span>
<span class="line"><span style="color:#BABED8;">    dry_run</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> bool</span><span style="color:#89DDFF;"> =</span><span style="color:#89DDFF;"> False</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">command</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/run</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> args_schema</span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;">RunArgs</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> help</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Run a task</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> run</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">args</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> RunArgs</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">):</span></span>
<span class="line"><span style="color:#BABED8;">    session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">output</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">json</span><span style="color:#89DDFF;">(</span></span>
<span class="line"><span style="color:#89DDFF;">        {</span></span>
<span class="line"><span style="color:#89DDFF;">            &quot;</span><span style="color:#C3E88D;">task</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#82AAFF;"> args</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">task</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">            &quot;</span><span style="color:#C3E88D;">retries</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#82AAFF;"> args</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">retries</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">            &quot;</span><span style="color:#C3E88D;">dry_run</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#82AAFF;"> args</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">dry_run</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">        }</span></span>
<span class="line"><span style="color:#89DDFF;">    )</span></span></code></pre></div><p>Input:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>/run build --retries 2 --dry_run</span></span></code></pre></div><h2 id="pitfalls" tabindex="-1">Pitfalls <a class="header-anchor" href="#pitfalls" aria-label="Permalink to &quot;Pitfalls&quot;">​</a></h2><h3 id="designing-commands-that-depend-on-advanced-shell-syntax" tabindex="-1">Designing commands that depend on advanced shell syntax <a class="header-anchor" href="#designing-commands-that-depend-on-advanced-shell-syntax" aria-label="Permalink to &quot;Designing commands that depend on advanced shell syntax&quot;">​</a></h3><p>If your UX depends on quoting, embedded whitespace, or repeated flag groups, the current router will be too small for that design.</p><h3 id="forgetting-canonical-names-in-middleware" tabindex="-1">Forgetting canonical names in middleware <a class="header-anchor" href="#forgetting-canonical-names-in-middleware" aria-label="Permalink to &quot;Forgetting canonical names in middleware&quot;">​</a></h3><p>Parsed commands use the canonical name after alias resolution.</p><h3 id="treating-parser-simplicity-as-a-bug-instead-of-a-design-constraint" tabindex="-1">Treating parser simplicity as a bug instead of a design constraint <a class="header-anchor" href="#treating-parser-simplicity-as-a-bug-instead-of-a-design-constraint" aria-label="Permalink to &quot;Treating parser simplicity as a bug instead of a design constraint&quot;">​</a></h3><p>Klix is not trying to replace a full shell parser. Keep commands readable and direct.</p>`,43)])])}const D=s(l,[["render",t]]);export{y as __pageData,D as default};
